param([switch]$SomenteVerificar)
$ErrorActionPreference = 'Stop'
$utf8 = New-Object Text.UTF8Encoding($false, $true)
$payload = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')) | ConvertFrom-Json
$base = (Get-Location).Path
if (-not (Test-Path -LiteralPath (Join-Path $base 'app/build.gradle.kts'))) {
    if ((Test-Path -LiteralPath (Join-Path $base 'build.gradle.kts')) -and (Test-Path -LiteralPath (Join-Path $base '../settings.gradle.kts'))) { $base = Split-Path $base -Parent }
    else { throw 'Abra o terminal na raiz do projeto IPTVPremium.' }
}
$base = [IO.Path]::GetFullPath($base)
function SafePath([string]$relative) {
    if (($relative -ne 'app/build.gradle.kts' -and $relative -notmatch '^app/src/main/java/[A-Za-z0-9_./-]+\.kt$') -or $relative.Contains('..')) { throw 'Caminho invalido.' }
    $path = [IO.Path]::GetFullPath((Join-Path $base $relative.Replace('/', [string][IO.Path]::DirectorySeparatorChar)))
    if (-not $path.StartsWith($base + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)) { throw 'Caminho fora do projeto.' }
    return $path
}
function HashText([string]$text) {
    $text = $text.TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    $text = ([regex]::Replace($text, '(?m)^// IPTV_[A-Z0-9_]+[ \t]*(?:\n|$)', '')).TrimEnd()
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($utf8.GetBytes($text)))).Replace('-', '').ToLowerInvariant() }
    finally { $sha.Dispose() }
}
$writes = @{}
$names = @{}
foreach ($source in $payload) {
    $path = SafePath $source.file
    $target = [string]$source.text
    if ((HashText $target) -ne $source.target) { throw 'Pacote inconsistente.' }
    $bom = $false
    $crlf = $true
    if (Test-Path -LiteralPath $path) {
        $bytes = [IO.File]::ReadAllBytes($path)
        $current = $utf8.GetString($bytes).TrimStart([char]0xFEFF)
        $hash = HashText $current
        if (@($source.accepted) -notcontains $hash) { throw "Versao diferente em $($source.file). Nada foi alterado. Envie o arquivo atual para adaptar." }
        if ($hash -eq $source.target) { continue }
        $bom = $bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191
        $crlf = $current.Contains("`r`n")
        foreach ($marker in [regex]::Matches($current, '(?m)^// IPTV_[A-Z0-9_]+[ \t]*\r?$')) {
            if (-not $target.Contains($marker.Value.TrimEnd())) { $target += "`n" + $marker.Value.TrimEnd() + "`n" }
        }
    } elseif (-not $source.create) { throw "Arquivo ausente: $($source.file). Nada foi alterado." }
    $target = $target.Replace("`r`n", "`n")
    if ($crlf) { $target = $target.Replace("`n", "`r`n") }
    $encoding = New-Object Text.UTF8Encoding([bool]$bom)
    $writes[$path] = [byte[]]($encoding.GetPreamble() + $encoding.GetBytes($target))
    $names[$path] = $source.file
}
if ($SomenteVerificar) { Write-Host 'Verificacao concluida. Nenhum arquivo alterado.' -ForegroundColor Green; return }
if ($writes.Count -eq 0) { Write-Host 'Posicao e comandos do teclado de busca ja corrigidos.' -ForegroundColor Green; return }
$backup = Join-Path $base ('.iptv-backups/teclado-busca-' + (Get-Date -Format 'yyyyMMdd-HHmmssfff'))
foreach ($path in $writes.Keys) {
    if (Test-Path -LiteralPath $path) {
        $copy = Join-Path $backup $names[$path]
        [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy))
        Copy-Item -LiteralPath $path -Destination $copy
    }
}
foreach ($path in $writes.Keys) {
    [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($path))
    $pending = $path + '.iptv-tmp'
    try { [IO.File]::WriteAllBytes($pending, $writes[$path]); Move-Item -LiteralPath $pending -Destination $path -Force }
    finally { if (Test-Path -LiteralPath $pending) { Remove-Item -LiteralPath $pending } }
}
Write-Host 'Concluido: teclado de busca na parte inferior e Enter aciona a tecla selecionada.' -ForegroundColor Green
Write-Host "Backup: $backup"
Write-Host 'Configuracoes locais, Firebase, versao e assinatura preservados.'
Write-Host 'Agora execute: powershell.exe -NoProfile -ExecutionPolicy Bypass -File .\Gerar-APKs.ps1'
Write-Host 'Instale sobre o aplicativo atual, sem desinstalar, usando a assinatura original.'
